    if (this.template == null || this.template.length() == 0) {
        return null;
    }

    // Then, check if the format of the URI is incorrect
    if (!uri.contains("://")) {
        return null;
    }

    // At this point, we know the URI is in the correct format, so we can extract the scheme and path
    int schemeSeparator = uri.indexOf("://");
    String scheme = uri.substring(1, schemeSeparator);
    String path = uri.substring(schemeSeparator + 1);

    // Now, we can match the path against the template
    Matcher matcher = this.template.matcher(path);
    if (matcher.matches()) {
        // If the path matches the template, we can extract the URI params
        Map<String, String> params = new HashMap<>();
        int groupCount = matcher.groupCount();
        for (int i = 0; i < groupCount; i++) {
            String paramName = this.params.get(i);
            String paramValue = matcher.group(i);
            params.put(paramName, paramValue);
