private String unescapeId(String input) {
    // Replace any escaped quote sequences with a single quote
    String output = input.replace("\\\"", "\"");

    // Remove any backslashes at the beginning or end of the string
    output = output.replace("^\\\\", "");
    output = output.replace("\\\\$", "");

