public static String base64Decode(final String s){
    // Edge case: empty string
    if (s.isEmpty()) {
        return s;
    }

    // Initialize the output string
    StringBuilder decoded = new StringBuilder();

    // Iterate over the string in chunks of 4 characters
    for (int i = 0; i < s.length(); i += 4) {
        // Get the next 4 characters
        String chunk = s.substring(i, i + 4);

        // Decode the chunk
        int decodedChunk = 0;
        for (int j = 0; j < chunk.length(); j++) {
            decodedChunk <<= 6;
            decodedChunk |= chunk.charAt(j) - 'A';
        }

        // Add the decoded chunk to the output string
        decoded.append((char) decodedChunk);
    }

    return decoded.toString();
}
