public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Step 1: Check if the name is null or empty
    if (nameStart == null || nameStart.isEmpty()) {
        return;
    }

    // Step 2: Create a new buffer to store the abbreviated name
    StringBuffer abbreviatedName = new StringBuffer();

    // Step 3: Iterate through each character in the name
    for (int i = nameStart; i < nameStart.length(); i++) {
        // Step 4: If the current character is a letter, append it to the abbreviated name
        if (Character.isLetter(nameStart.charAt(i))) {
            abbreviatedName.append(nameStart.charAt(i));
        }
    }

